#!/usr/bin/env node
// Makes the sample video of the animation screens (libs/music-motion/sample/sample.mp4) with ffmpeg: moving gradients and a
// box that pulses on the beat, over a synthesized kick and hat at the same tempo. Everything is generated by the filters, so no
// third party holds rights to it. The committed file is the truth: this script is only for regenerating it.
//
//   node scripts/make-sample-video.mjs [out.mp4]      (or: npm run sample:video)
import { spawnSync } from 'node:child_process';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
export const DEFAULT_OUT = resolve(here, '../libs/music-motion/sample/sample.mp4');

export const SAMPLE = { seconds: 12, bpm: 96, width: 1280, height: 720, fps: 30 };

/** The arguments of ffmpeg for the sample: a video made of gradients and a beat box, an audio made of a kick and a hat. */
export function ffmpegArgs({ out = DEFAULT_OUT, seconds, bpm, width, height, fps } = {}) {
  const s = { ...SAMPLE, ...(seconds && { seconds }), ...(bpm && { bpm }), ...(width && { width }), ...(height && { height }), ...(fps && { fps }) };
  const beat = 60 / s.bpm;
  const box = Math.round(s.height / 3);
  const video =
    `gradients=s=${s.width}x${s.height}:r=${s.fps}:d=${s.seconds}:c0=0x101018:c1=0xff5a3c:c2=0x2a9d8f:c3=0xf4f1ea:speed=0.015:nb_colors=3,` +
    `drawbox=x=(iw-${box})/2:y=(ih-${box})/2:w=${box}:h=${box}:color=0xf4f1ea@0.9:t=fill:enable='lt(mod(t,${beat.toFixed(4)}),0.12)',` +
    `drawbox=x=(iw-${box * 2})/2:y=(ih-${box * 2})/2:w=${box * 2}:h=${box * 2}:color=0xf4f1ea@0.6:t=6:enable='lt(mod(t+${(beat / 2).toFixed(4)},${beat.toFixed(4)}),0.08)',` +
    `format=yuv420p`;
  const audio = `aevalsrc='0.7*sin(2*PI*(55+90*exp(-30*mod(t,${beat.toFixed(4)})))*t)*exp(-9*mod(t,${beat.toFixed(4)}))+0.12*(random(0)-0.5)*exp(-40*mod(t+${(beat / 2).toFixed(4)},${beat.toFixed(4)}))':s=44100:d=${s.seconds}`;
  return [
    '-y', '-hide_banner', '-loglevel', 'error',
    '-f', 'lavfi', '-i', video,
    '-f', 'lavfi', '-i', audio,
    '-c:v', 'libx264', '-preset', 'slow', '-crf', '30', '-movflags', '+faststart',
    '-c:a', 'aac', '-b:a', '80k',
    '-t', String(s.seconds),
    out,
  ];
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const out = process.argv[2] ? resolve(process.argv[2]) : DEFAULT_OUT;
  const r = spawnSync('ffmpeg', ffmpegArgs({ out }), { stdio: 'inherit' });
  if (r.error) {
    console.error('ffmpeg is needed to make the sample video:', r.error.message);
    process.exit(1);
  }
  process.exit(r.status ?? 1);
}
